import java.time.format.DateTimeFormatter
import java.math.BigDecimal
import scala.collection.mutable

/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's powerful type system with:
 * - Generic types with proper variance annotations
 * - Algebraic data types (ADTs) with sealed traits
 * - Pattern matching for type-safe dispatch
 * - Immutable data structures
 * - Type classes for extensible behaviors
 */

/**
 * Enumeration of token types representing different categories of tokenized data.
 */
sealed trait TokenType extends Product with Serializable

object TokenType {
  case object STRING extends TokenType
  case object NUMERIC extends TokenType
  case object TEMPORAL extends TokenType
  case object STRUCTURED extends TokenType
  case object BINARY extends TokenType
  case object NULL extends TokenType
}

/**
 * Immutable token representation with value, type, and optional metadata.
 *
 * @param value The string representation of the token
 * @param tokenType The type of the token
 * @param metadata Optional metadata as key-value pairs
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return a new token with additional metadata.
   *
   * @param kv Key-value pairs to add to metadata
   * @return New token with merged metadata
   */
  def withMetadata(kv: (String, Any)*): Token = {
    copy(metadata = metadata ++ kv.toMap)
  }
}

/**
 * Abstract base class for all tokenizers with generic input type.
 *
 * @tparam T The type of values this tokenizer can process
 */
abstract class BaseTokenizer[T] {
  /**
   * Convert a value to a token.
   *
   * @param value The value to tokenize
   * @return The resulting token
   */
  def tokenize(value: T): Token

  /**
   * Lazily tokenize multiple values.
   *
   * @param values Iterable of values to tokenize
   * @return Iterator of tokens
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
 * Tokenizer for string and bytes types.
 *
 * @param encoding The character encoding to use for bytes (default: UTF-8)
 * @param normalizer Optional function to normalize strings
 */
case class StringTokenizer(
  encoding: String = "utf-8",
  normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(str) => str
      case Right(bytes) => new String(bytes, encoding)
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }
