/**
 * Tokenizer for numeric types with precision handling.
 *
 * @param precision Number of decimal places for floating point values
 * @param formatOptions Additional formatting options
 */
case class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Long, Either[Double, BigDecimal]]] {

  def tokenize(value: Either[Long, Either[Double, BigDecimal]]): Token = {
    val (strValue, originalType) = value match {
      case Left(longVal) => (longVal.toString, "Long")
      case Right(doubleOrDecimal) =>
        doubleOrDecimal match {
          case Left(doubleVal) => (f"$doubleVal%.${precision}f", "Double")
          case Right(decimalVal) => (decimalVal.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString, "BigDecimal")
