 *
 * @param formatStr Optional custom format string. If None, uses ISO format.
 */
case class TemporalTokenizer(
  formatStr: Option[String] = None
) extends BaseTokenizer[Either[LocalDate, LocalDateTime]] {

  private val ISO_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE

  def tokenize(value: Either[LocalDate, LocalDateTime]): Token = {
    val formatted = value match {
      case Left(date) =>
        formatStr.map(DateTimeFormatter.ofPattern).getOrElse(DATE_FORMAT).format(date)
      case Right(dateTime) =>
        formatStr.map(DateTimeFormatter.ofPattern).getOrElse(ISO_FORMAT).format(dateTime)
