  private def processToken(word: String): Option[String] = {
    var processed = if (stripPunctuation) word.filterNot(punctuation.contains) else word

    if (lowercase) processed = processed.toLowerCase

    if (processed.length < minLength) None
    else {
      maxLength match {
        case Some(max) if processed.length > max => Some(processed.take(max))
        case _ => Some(processed)
      }
    }
