   * Tokenize text and return tokens with character positions.
   *
   * @param text Input text to tokenize
   * @return List of tuples (token_string, start_pos, end_pos)
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    @tailrec
    def findPositions(words: Array[String], startIndex: Int, acc: List[(String, Int, Int)]): List[(String, Int, Int)] = {
      if (words.isEmpty) acc.reverse
      else {
        val word = words.head
        val start = text.indexOf(word, startIndex)
        val end = start + word.length
        processToken(word) match {
          case Some(processed) => findPositions(words.tail, end, (processed, start, end) :: acc)
          case None => findPositions(words.tail, end, acc)
        }
      }
    }
    findPositions(text.split("\\s+"), 0, Nil)
  }

