/**
 * Universal tokenizer that handles multiple types using pattern matching.
 *
 * This demonstrates Scala's type-safe pattern matching as an alternative
 * to Python's runtime type checking and method overloading.
 */
case class UniversalTokenizer() {
  private val stringTokenizer = StringTokenizer()
  private val numericTokenizer = NumericTokenizer()
  private val temporalTokenizer = TemporalTokenizer()

  /**
   * Tokenize a value of any supported type.
   *
   * @param value The value to tokenize
   * @return The resulting token
   */
  def tokenize(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)
    case str: String => stringTokenizer.tokenize(Left(str))
    case bytes: Array[Byte] => stringTokenizer.tokenize(Right(bytes))
    case long: Long => numericTokenizer.tokenize(Left(long))
    case int: Int => numericTokenizer.tokenize(Left(int.toLong))
    case double: Double => numericTokenizer.tokenize(Right(Left(double)))
    case decimal: BigDecimal => numericTokenizer.tokenize(Right(Right(decimal)))
    case date: LocalDate => temporalTokenizer.tokenize(Left(date))
    case dateTime: LocalDateTime => temporalTokenizer.tokenize(Right(dateTime))
    case tokenizable: ToToken => Token(tokenizable.toToken, TokenType.STRUCTURED)
    case _ => Token(value.toString, TokenType.STRING, Map("fallback" -> true))
  }

  /**
   * Tokenize a batch of values.
   *
   * @param values The values to tokenize
   * @return Iterator of tokens
   */
  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

