 */
trait ToToken {
  def toToken: String
}

/**
 * Whitespace tokenizer for basic text tokenization.
 *
 * Splits text by whitespace and applies optional processing like
 * lowercasing, length filtering, and punctuation stripping.
 */
case class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set(',', '.', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  /**
   * Process a single word into a token string.
   *
   * @param word The word to process
   * @return Option containing the processed token or None if filtered out
   */
  private def processToken(word: String): Option[String] = {
    var processed = if (stripPunctuation) word.filterNot(punctuation.contains) else word

    if (lowercase) processed = processed.toLowerCase

    if (processed.length < minLength) None
    else {
      maxLength match {
        case Some(max) if processed.length > max => Some(processed.take(max))
        case _ => Some(processed)
      }
    }
  }

  /**
   * Tokenize text into a list of Token objects.
   *
   * @param text Input text to tokenize
   * @return List of Token objects
   */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
   * Tokenize text into a list of token strings.
   *
   * @param text Input text to tokenize
   * @return List of token strings
   */
  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  /**
   * Tokenize text and return tokens with character positions.
   *
   * @param text Input text to tokenize
   * @return List of tuples (token_string, start_pos, end_pos)
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    @tailrec
    def findPositions(words: Array[String], startIndex: Int, acc: List[(String, Int, Int)]): List[(String, Int, Int)] = {
      if (words.isEmpty) acc.reverse
      else {
        val word = words.head
        val start = text.indexOf(word, startIndex)
        val end = start + word.length
        processToken(word) match {
          case Some(processed) => findPositions(words.tail, end, (processed, start, end) :: acc)
          case None => findPositions(words.tail, end, acc)
        }
      }
    }
    findPositions(text.split("\\s+"), 0, Nil)
  }

  /**
   * Count the number of tokens in the text.
   *
   * @param text Input text
   * @return Number of tokens
   */
  def countTokens(text: String): Int = tokenize(text).size
}

/**
 * Builder for creating custom tokenizers with fluent interface.
 *
 * @tparam T The type of values the resulting tokenizer will process
 */
case class TokenizerBuilder[T]() {
  private val normalizers = mutable.ListBuffer.empty[String => String]
  private val validators = mutable.ListBuffer.empty[T => Boolean]
  private var metadata: Map[String, Any] = Map.empty

  /**
   * Add a normalizer function to the builder.
   *
   * @param normalizer The normalizer function
   * @return This builder for method chaining
   */
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  /**
   * Add a validator function to the builder.
   *
   * @param validator The validator function
   * @return This builder for method chaining
   */
  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  /**
   * Add metadata to the builder.
   *
   * @param kv Key-value pairs for metadata
   * @return This builder for method chaining
   */
  def withMetadata(kv: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kv.toMap
    this
  }

  /**
   * Build the final tokenizer function.
   *
   * @return A function that tokenizes values of type T
   */
  def build: T => Token = { value: T =>
    // Validate
    validators.find(!_(value)).foreach(_ =>
      throw new IllegalArgumentException(s"Validation failed for $value")
    )

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach(normalizer => strValue = normalizer(strValue))

    Token(strValue, TokenType.STRING, metadata)
  }
}

/**
 * Factory object providing convenience methods for tokenization.
 */
object Tokenizer {
  /**
   * Create a simple tokenizer for strings.
   *
   * @param normalizer Optional normalizer function
   * @return A StringTokenizer
   */
  def apply(normalizer: String => String = identity): StringTokenizer = {
    StringTokenizer(normalizer = normalizer)
  }

  /**
   * Create a whitespace tokenizer.
   *
   * @param lowercase Whether to convert tokens to lowercase
   * @param minLength Minimum token length
   * @param maxLength Maximum token length
   * @param stripPunctuation Whether to strip punctuation
   * @return A WhitespaceTokenizer
   */
  def whitespace(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ): WhitespaceTokenizer = {
    WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
  }

  /**
   * Create a numeric tokenizer.
   *
   * @param precision Decimal precision for floating point numbers
   * @param formatOptions Additional formatting options
   * @return A NumericTokenizer
   */
  def numeric(precision: Int = 6, formatOptions: Map[String, Any] = Map.empty): NumericTokenizer = {
    NumericTokenizer(precision, formatOptions)
  }

  /**
   * Create a temporal tokenizer.
   *
   * @param formatStr Optional custom date/time format
   * @return A TemporalTokenizer
   */
  def temporal(formatStr: Option[String] = None): TemporalTokenizer = {
    TemporalTokenizer(formatStr)
  }

  /**
   * Create a universal tokenizer.
   *
   * @return A UniversalTokenizer
   */
  def universal: UniversalTokenizer = UniversalTokenizer()

  /**
   * Tokenize a single value using the universal tokenizer.
   *
   * @param value The value to tokenize
   * @return The resulting token
   */
  def tokenize(value: Any): Token = universal.tokenize(value)

  /**
   * Tokenize a batch of values using the universal tokenizer.
   *
   * @param values The values to tokenize
   * @return Iterator of tokens
   */
  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] = universal.tokenizeBatch(values)

  /**
   * Add metadata to a token (convenience method).
   *
   * @param token The original token
   * @param kv Key-value pairs to add
   * @return New token with added metadata
   */
  def withMetadata(token: Token, kv: (String, Any)*): Token = token.withMetadata(kv: _*)

  /**
   * Convert a value to a token string.
   *
   * @param value The value to convert
   * @return The token string
   */
  def toToken(value: Any): String = tokenize(value).value
}

/**
 * Companion object for ToToken type class with implicit conversions.
 */
object ToToken {
  implicit def anyToToken(value: Any)(implicit toTokenable: ToToken): ToToken = toTokenable
}

