    @tailrec
    def findPositions(words: Array[String], startIndex: Int, acc: List[(String, Int, Int)]): List[(String, Int, Int)] = {
      if (words.isEmpty) acc.reverse
      else {
        val word = words.head
        val start = text.indexOf(word, startIndex)
        val end = start + word.length
        processToken(word) match {
          case Some(processed) => findPositions(words.tail, end, (processed, start, end) :: acc)
