  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Long, Either[Double, BigDecimal]]] {

  def tokenize(value: Either[Long, Either[Double, BigDecimal]]): Token = {
    val (strValue, originalType) = value match {
      case Left(longVal) => (longVal.toString, "Long")
      case Right(doubleOrDecimal) =>
        doubleOrDecimal match {
          case Left(doubleVal) => (s"% .${precision}f".format(doubleVal), "Double")
          case Right(decimalVal) => (decimalVal.setScale(precision, BD.RoundingMode.HALF_UP).toString, "BigDecimal")
