 * Splits text by whitespace and applies optional processing like
 * lowercasing, length filtering, and punctuation stripping.
 */
case class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
