  private val punctuation = Set(',', '.', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  /**
   * Process a single word into a token string.
   *
   * @param word The word to process
   * @return Option containing the processed token or None if filtered out
   */
  private def processToken(word: String): Option[String] = {
    var processed = if (stripPunctuation) word.filterNot(punctuation.contains) else word

    if (lowercase) processed = processed.toLowerCase

    if (processed.length < minLength) None
    else {
      maxLength match {
        case Some(max) if processed.length > max => Some(processed.take(max))
        case _ => Some(processed)
      }
    }
  }

  /**
   * Tokenize text into a list of Token objects.
   *
   * @param text Input text to tokenize
   * @return List of Token objects
   */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
   * Tokenize text into a list of token strings.
   *
   * @param text Input text to tokenize
   * @return List of token strings
   */
  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

