   *
   * @param validator The validator function
   * @return This builder for method chaining
   */
  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  /**
   * Add metadata to the builder.
   *
   * @param kv Key-value pairs for metadata
   * @return This builder for method chaining
   */
  def withMetadata(kv: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kv.toMap
    this
  }

  /**
   * Build the final tokenizer function.
   *
   * @return A function that tokenizes values of type T
   */
  def build: T => Token = { value: T =>
    // Validate
    validators.find(!_(value)).foreach(_ =>
      throw new IllegalArgumentException(s"Validation failed for $value")
    )

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach(normalizer => strValue = normalizer(strValue))

    Token(strValue, TokenType.STRING, metadata)
  }
